from typing import List
import math

def factorize(n: int) -> List[int]:
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    factors = []
    divisor = 2
    while n > 1:
        if n % divisor == 0:
            if is_prime(divisor):
                factors.append(divisor)
                n //= divisor
            else:
                divisor += 1
        else:
            divisor += 1

    return factors

