def do_algebra(operator, operand):
    if len(operator) != len(operand) - 1:
        raise ValueError("Operator list length should be one less than operand list length")

    result = operand[0]
    operand_index = 1

    for op in operator:
        if op == '+':
            result += operand[operand_index]
        elif op == '-':
            result -= operand[operand_index]
        elif op == '*':
            result *= operand[operand_index]
        elif op == '//':
            result //= operand[operand_index]
        elif op == '**':
            result **= operand[operand_index]

        operand_index += 1

    return result

